def practice6(r,f):
    r.start(6,'определить требования к информационной системе подготовки карточек компьютерных систем ООО «Юкомс», классифицировать их по FURPS+ и задать проверяемые условия приёмки.')
    r.h('Этапы выполнения работы')
    r.p('За основу приняты проблемы P-01–P-06 из практики 3, потоки F01–F14 из практики 2 и целевой процесс из практики 5. Последовательно определены функции системы, ограничения качества, критерии проверки и связи с результатами автоматизации. Требования являются проектными: их согласование с сотрудниками и проверка на реальных данных включены в план внедрения.')
    r.h('Границы и источники требований')
    r.p('Система охватывает справочник компонентов, версии BOM, техническое согласование, расчёт цены и массы, изображения, подготовку карточки, передачу в Ozon, статусы и аудит. Бухгалтерский учёт, управление производственными станками и оформление клиентских заказов в границы первой версии не входят. Источники цен и остатков подключаются через согласованные файлы; прямой обмен добавляется только после проверки доступного интерфейса.')
    r.p('Префикс F- обозначает функциональные требования, а F без дефиса — информационные потоки. Префикс P- в пределах классификации FURPS+ обозначает производительность; коды проблем всегда сопровождаются словом «проблема». Для каждого требования указан наблюдаемый результат, который можно включить в протокол испытаний.')
    r.table('Функциональные требования',['Код','Требование','Критерий приёмки'],[
    ['F-01','Импортировать компоненты, цены и остатки с датой источника; отклонять некорректные строки.','На файле из 100 строк корректные записи загружены; для каждой ошибочной строки есть причина; повтор не создаёт дубликатов.'],
    ['F-02','Хранить черновые и согласованные версии BOM; не изменять согласованную версию на месте.','После замены компонента появилась новая версия; прежняя BOM и связанные карточки воспроизводятся.'],
    ['F-03','Проверять совместимость по утверждённым правилам и блокировать согласование при критической ошибке.','Все критические ошибки в контрольном наборе обнаружены; протокол указывает компонент и правило.'],
    ['F-04','Показывать зависимые BOM и карточки при изменении компонента, цены или изображения.','Для контрольного компонента найдены все заданные зависимости; изменённые карточки помечены для проверки.'],
    ['F-05','Рассчитывать себестоимость, цену и массу по версии BOM и снимку исходных значений.','Результат совпадает с ручным расчётом до 0,01 руб. и установленной точности массы.'],
    ['F-06','Связывать изображения с конфигурацией и отмечать необходимость их пересмотра.','Замена корпуса сбрасывает признак актуальности изображения; публикация без подтверждения заблокирована.'],
    ['F-07','Формировать карточку по шаблону категории, проверять обязательные поля до передачи.','Каждое пропущенное обязательное поле отображается в перечне замечаний; отправка недоступна.'],
    ['F-08','Передавать утверждённый пакет и сохранять отдельную попытку публикации.','Для отправки сохранены пакет, версия BOM, автор, время, внутренний ключ и внешний идентификатор при его наличии.'],
    ['F-09','Учитывать ожидание, успех, отказ и неопределённый результат; контролировать повторные операции.','Тайм-аут не превращается в успех; повторный запрос сначала проверяет известную попытку.'],
    ['F-10','Сохранять историю значимых изменений и действий пользователей.','По карточке восстановлены авторы, версии, согласования и все попытки отправки; обычный пользователь не удаляет историю.'],
    ['F-11','Формировать реестр карточек и отчёт по срокам, ошибкам и актуальности.','Итоги за период совпадают с контрольной выборкой событий и фильтрами по ответственному.'],
    ['F-12','Разграничивать доступ менеджера, производства, дизайнера, директора и администратора.','Каждая запрещённая операция из матрицы ролей отклонена сервером независимо от интерфейса.'],
    ],[1.15,6.5,7.85])
    r.table('Качество и ограничения по FURPS+',['Код','Категория и требование','Проверка'],[
    ['U-01','Удобство: единый экран карточки с BOM, расчётом, изображениями и замечаниями.','После обучения пользователь выполняет 4 из 5 типовых сценариев без помощи.'],
    ['U-02','Удобство: ошибки содержат поле, причину и способ исправления.','Для всех ошибок контрольного набора отображаются понятные сообщения.'],
    ['U-03','Удобство: инструкция и контекстные подсказки доступны из системы.','Поиск описания публикации занимает не более двух переходов.'],
    ['R-01','Надёжность: согласование BOM и запись попытки выполняются атомарно в своей операции.','Принудительный сбой не оставляет частично сохранённую запись.'],
    ['R-02','Надёжность: резервное копирование ежедневно; RPO ≤ 24 ч, RTO ≤ 4 ч.','Восстановление из копии на отдельной среде укладывается в цели и проверку целостности.'],
    ['R-03','Надёжность: внешняя недоступность не блокирует подготовку черновиков.','При отключении Ozon черновик сохраняется; попытки остаются в очереди с наблюдаемым статусом.'],
    ['P-01','Производительность: 95-й процентиль открытия карточки ≤ 2 с при 5 одновременных пользователях.','Тест на 10 000 компонентов, 1 000 BOM и 2 000 карточек; внешняя сеть исключена из метрики.'],
    ['P-02','Производительность: проверка одной BOM до 30 строк ≤ 3 с.','100 повторов на пилотной конфигурации; фиксируются размер и время.'],
    ['P-03','Производительность: импорт 10 000 строк ≤ 5 мин без потери записей.','Загрузка контрольного файла с протоколом, итоговыми счётчиками и замером времени.'],
    ['S-01','Сопровождаемость: правила совместимости и шаблоны изменяются без правки исходного кода.','Администратор правил добавляет правило через предусмотренный механизм; результат проверяется тестом.'],
    ['S-02','Сопровождаемость: интеграция отделена от предметных расчётов.','Замена тестового адаптера не меняет алгоритм цены и структуру BOM.'],
    ['S-03','Сопровождаемость: поставка содержит инструкцию развёртывания, миграции и восстановления.','Другой специалист разворачивает проверочную среду по инструкции.'],
    ['X-01','Ограничение интерфейса: браузерный доступ в локальной сети; внешние подключения по защищённому каналу.','Нет необходимости устанавливать отдельный клиент; проверена выбранная версия браузера.'],
    ['X-02','Ограничение реализации: один канал Ozon, один контур справочников и пилотная группа до 5 пользователей.','Состав поставки совпадает с утверждёнными границами; расширения оформляются отдельно.'],
    ['X-03','Ограничение проекта: 12 недель, 432 чел.-ч, бюджет до 600 тыс. руб.','План и смета практик 11–12 согласованы; изменение проходит оценку влияния.'],
    ],[1.2,7.7,6.6])
    r.h('Прослеживаемость и приоритеты')
    r.table('Связь проблем и требований',['Проблема','Требования','Управленческий результат'],[
    ['P-01: повторный ввод','F-01, F-05, F-07','Единый расчёт и заполнение карточки из общих данных.'],['P-02: несовместимость','F-02, F-03','Протокол проверки и техническое согласование BOM.'],['P-03: несогласованная замена','F-04, F-06, F-10','Полный перечень зависимых карточек и история изменения.'],['P-04: устаревшие источники','F-01, F-05, F-11','Контроль даты цен и остатков в реестре.'],['P-05: поздняя ошибка полей','F-07, U-02','Предварительная валидация и список исправлений.'],['P-06: потеря истории','F-08–F-12, R-01–R-03','Прослеживаемость публикаций и восстановление после сбоя.'],
    ],[5,3.7,6.8])
    r.p('Обязательный минимум включает все требования F, R и X: без них нельзя безопасно связать конфигурацию, карточку и результат публикации. Требования U, P и S также входят в критерии приёмки; допустимые изменения их порогов оформляются до пилота. Измеримые пороги характеризуют проектируемую систему, а не уже достигнутый результат.')
    r.h('Выводы');r.p('Сформированы 27 требований: 12 функциональных и по 3 требования в группах U, R, P, S и «+». Для каждого определена проверка, а функциональность связана с шестью проблемами процесса. Реестр задаёт основу сравнения продуктов, сценариев использования и приёмочных испытаний.')

def practice7(r,f):
    r.start(7,'сравнить готовые программные продукты с требованиями проекта и обосновать способ автоматизации подготовки карточек ООО «Юкомс».')
    r.h('Этапы и условия сравнения')
    r.p('Проведён обзор официальных описаний и тарифов трёх решений: МойСклад, «1С:Управление нашей фирмой» и «1С-Битрикс: Управление сайтом». Сведения проверены 27.09.2026. Сравниваются типовые функции и необходимость адаптации под BOM компьютеров, техническую совместимость и управляемую публикацию. Фактическое внедрение или испытание этих продуктов не выполнялось.')
    r.p('В существующей учебной модели используются таблицы, файлы изображений, переписка и кабинет продавца. Они позволяют выполнить отдельные операции, но не обеспечивают общей версии BOM и истории публикаций. Требования к специализированным правилам совместимости и пересчёту зависимых карточек имеют решающее значение при выборе.')
    r.h('Рассмотренные продукты')
    r.p('МойСклад ориентирован на оперативный учёт товаров, остатков и производства. Технологические карты описывают состав изделия; предусмотрены расчёт себестоимости и работа с Ozon, включая цены и остатки [7, 8]. Для проекта важна быстрая организация справочников. Наличие всех нужных проверок сокета, памяти, питания и зависимости изображений в изученных описаниях не подтверждено: их реализацию требуется проверять отдельно.')
    r.p('«1С:Управление нашей фирмой» объединяет торговлю, склад, закупки, производство и сборочные операции [9]. Продукт подходит как основа учётного контура, но для рассматриваемой задачи необходимо исследовать формат BOM, ведение версий и процедуру технического согласования. Типовые возможности нельзя автоматически считать эквивалентом всех требований F-02–F-10.')
    r.p('«1С-Битрикс: Управление сайтом», редакция «Бизнес», предоставляет инструменты торгового каталога и интернет-магазина [11]. Это удобная основа публикации товарного содержания, однако техническая конфигурация компьютера и производственная спецификация не являются единственным назначением CMS. Проверку совместимости и обмен с Ozon следует оценивать как отдельные доработки либо модули.')
    r.table('Укрупнённое сравнение по FURPS+',['Группа','МойСклад','1С:УНФ','1С-Битрикс'],[
    ['F','Учёт и техкарты; отраслевые проверки требуют уточнения.','Сборка и учёт; адаптация маршрута согласования.','Каталог и контент; BOM и технические правила — отдельная задача.'],
    ['U','Облачный интерфейс; проверить сценарий менеджера.','Рабочие места учёта; потребуется обучение.','Административная панель каталога; настройка форм.'],
    ['R','Облачная эксплуатация; проверить условия восстановления и выгрузки.','Ответственность зависит от локального или облачного размещения.','Резервирование и восстановление зависят от размещения и настройки.'],
    ['P','Пороговые значения проекта проверяются на тестовых данных.','Пороговые значения проверяются на выбранной конфигурации.','Пороговые значения проверяются с установленными модулями.'],
    ['S','Интеграции и расширения; зависимость от сервиса.','Доработка конфигурации или расширений; требуется профильный специалист.','Модули и адаптеры; учитывать обновление CMS.'],
    ['+','Регулярная подписка; условия опций и пользователей.','Лицензии рабочих мест; обслуживание по договору.','Лицензия, продление, хостинг и возможные модули.'],
    ],[1.0,4.85,4.85,4.8])
    r.h('Оценка соответствия функциональности')
    r.p('Оценки в таблице 7.2 являются аналитическими, а не результатом испытаний: 2 — базовая возможность описана производителем; 1 — есть смежная функция, требуется настройка или адаптация; 0 — подтверждение в изученных материалах отсутствует. Нулевой балл не доказывает невозможность реализации. Веса отражают приоритеты именно данного учебного проекта.')
    criteria=[('Состав изделия и BOM',.20,2,2,1),('Отраслевые правила совместимости',.25,0,0,0),('Версии и анализ зависимостей',.20,1,1,1),('Каталог, характеристики, изображения',.15,1,1,2),('Обмен с Ozon',.10,2,1,1),('Управленческий учёт и отчёты',.10,2,2,1)]
    r.table('Взвешенная оценка типового покрытия',['Критерий','Вес','МойСклад','1С:УНФ','Битрикс'],[[a,f'{b:.2f}'.replace('.',','),c,d,e] for a,b,c,d,e in criteria]+[['Итог, из 2','1,00','1,15','1,05','0,90']],[6.6,1.3,2.8,2.4,2.4])
    r.p('Итог рассчитывается как сумма произведений весов на баллы. Наибольшая оценка МойСклад связана с сочетанием состава изделия, учёта и готового обмена. Ни у одного из трёх вариантов по использованным источникам не подтверждён весь специфический контур совместимости и прослеживаемости. Поэтому решение нельзя принимать только по итоговому баллу или цене лицензии.')
    r.h('Стоимость приобретения и эксплуатации')
    r.table('Публичные цены и непокрытые статьи затрат',['Вариант','Публичная цена на дату обзора','Что учитывать дополнительно'],[
    ['МойСклад «Проф»','4 100 руб./мес. при помесячной оплате; 3 280 руб./мес. при оплате за год. Опция «Производство» — 1 400 руб./мес. [6].','Число пользователей, состав подключённых опций, импорт, настройка и доработки.'],
    ['1С:УНФ, пакетная локальная версия','55 900 руб. за 5 рабочих мест [10].','Настройка, сопровождение 1С:ИТС, инфраструктура и специальные правила.'],
    ['1С-Битрикс «Бизнес»','96 500 руб.; указанное на сайте продление — 24 125 руб. [12].','Хостинг, внедрение, адаптер Ozon, техническая BOM и поддержка модулей.'],
    ],[3.6,6.1,5.8])
    r.p('Для сопоставимого примера МойСклад при помесячной оплате с отдельно подключённым производством даёт (4 100 + 1 400) × 12 = 66 000 руб. за год до дополнительных опций. Для 1С:УНФ нижняя известная часть затрат первого года — 55 900 руб., но стоимость обслуживания и адаптации не определена. Для Битрикс известна лицензия 96 500 руб.; хостинг и доработки также требуют оценки. Эти суммы не являются полной стоимостью внедрения и не сравниваются напрямую с 592 000 руб. собственного проекта.')
    r.h('Выбор способа автоматизации')
    r.p('Для учебного проекта выбрана разработка компактного специализированного веб-приложения с готовой СУБД и отдельными адаптерами обмена. Разрабатываются правила и связи «компонент — версия BOM — карточка — попытка публикации». Существующий учёт организации не заменяется. Такой выбор позволяет прямо реализовать F-02–F-10 и ограничить первую поставку одним процессом и одним каналом.')
    r.p('Выбор не означает доказанного финансового превосходства разработки над готовыми продуктами. Его основания — управляемость предметных правил, точная прослеживаемость версий и учебная задача проектирования. До реального запуска следует проверить прототип в МойСклад и 1С:УНФ, запросить оценку адаптации и сравнить полную стоимость владения. Если готовое решение выполняет обязательные сценарии дешевле, архитектурное решение подлежит пересмотру.')
    r.h('Выводы');r.p('Рассмотрены три продукта, сопоставлены группы FURPS+, ключевые функции и публичные цены. Обоснован проект собственного специализированного приложения без замены всего учётного контура. Основной риск выбора — недооценка затрат на сопровождение; он учитывается в смете и расчёте экономического эффекта практики 12.')

CASES=[
('UC-01','Импортировать исходные данные','Менеджер','F-01','Получен согласованный файл поставщика или склада; задано сопоставление колонок.','Менеджер выбирает источник и файл. Система проверяет структуру, коды, единицы измерения и даты; показывает предварительный протокол. Менеджер подтверждает корректные строки; система сохраняет новую загрузку и её происхождение.','Ошибочные строки не загружаются и перечисляются в протоколе. Повторный файл определяется по идентификатору загрузки и содержанию; пользователь получает предупреждение.','Корректные данные доступны для расчёта; исходный файл и результаты контроля сохранены.'),
('UC-02','Подготовить и согласовать BOM','Производственный специалист','F-02, F-03, F-04','Компоненты заведены; у пользователя есть право согласования состава.','Специалист создаёт черновик версии, выбирает компоненты и количества, запускает согласование. Система выполняет UC-03, показывает результат и зависимые карточки. После подтверждения фиксирует согласованную неизменяемую версию.','Критическая ошибка запрещает согласование. При одновременном изменении черновика система требует обновить данные. Замена в согласованной BOM выполняется через новую версию.','Имеется согласованная версия либо черновик с замечаниями; затронутые карточки помечены для пересмотра.'),
('UC-03','Проверить совместимость','Производственный специалист','F-03','Состав BOM задан; доступна утверждённая версия правил.','Система проверяет совместимость сокета процессора и платы, тип памяти, габариты компонентов и расчётный запас питания. Формирует протокол по каждому правилу с уровнем ошибки; специалист просматривает результат.','При отсутствии обязательной характеристики результат считается неопределённым, а согласование блокируется. Предупреждение допускает продолжение только с зафиксированным решением ответственного.','Протокол связан с конкретной версией BOM и набором правил; критические замечания видны.'),
('UC-04','Рассчитать параметры','Менеджер','F-05','Выбрана согласованная BOM; доступны актуальные цены, масса, затраты на сборку и наценка.','Менеджер выбирает снимок источников и параметры цены. Система рассчитывает себестоимость, цену и массу; показывает расшифровку по строкам. Менеджер проверяет результат и сохраняет ведомость.','Отсутствующая цена не заменяется нулём. Устаревший источник помечается; итог для публикации не утверждается до обновления или явно разрешённого решения по регламенту.','Ведомость хранит исходные значения, формулу, дату, автора и версию BOM.'),
('UC-05','Подготовить изображения','Дизайнер','F-06','Получено задание с согласованной конфигурацией и требуемым видом изображения.','Дизайнер загружает файлы и связывает их с конфигурацией. Система проверяет допустимый формат и наличие связи с BOM. Дизайнер подтверждает соответствие внешнего вида; результат становится доступен менеджеру.','Неподдерживаемый файл отклоняется. При замене корпуса или иного видимого компонента прежнее подтверждение теряет актуальность.','Карточка имеет актуальный комплект изображений либо статус необходимости доработки.'),
('UC-06','Сформировать карточку','Менеджер','F-04–F-07','Есть согласованная BOM, проверенные изображения и шаблон выбранной категории.','Менеджер выбирает конфигурацию. Система выполняет UC-04, заполняет характеристики и изображения, проверяет обязательные поля. Менеджер уточняет описание, просматривает итог и утверждает пакет.','При изменении BOM или цены после формирования система помечает пакет устаревшим. Незаполненное поле блокирует утверждение; изменения сохраняются в черновике.','Создана утверждённая версия карточки с фиксированными исходными данными, готовая к отправке.'),
('UC-07','Опубликовать карточку','Менеджер; внешний участник Ozon','F-08, F-10','Карточка утверждена; права и параметры подключения действуют; нет конфликтующей незавершённой попытки.','Менеджер подтверждает отправку. Система повторно проверяет версию, создаёт попытку и сохраняет пакет до внешнего вызова. Адаптер передаёт данные; полученный идентификатор обработки связывается с попыткой. Интерфейс показывает ожидание результата.','Если ответ потерян, состояние остаётся неопределённым. Автоматическое создание новой внешней операции не допускается до проверки уже отправленной. Локальная ошибка сохраняется с описанием.','Пакет не потерян; известна попытка и её состояние. Успех передачи ещё не означает публикацию.'),
('UC-08','Уточнить результат публикации','Менеджер; внешний участник Ozon','F-09, F-10','Есть сохранённая попытка и доступные данные для сопоставления внешнего результата.','Система по расписанию или запросу менеджера получает статус. Сопоставляет ответ с попыткой, сохраняет исходные замечания и итог. При успешной обработке карточка отмечается опубликованной; при отказе возвращается на доработку.','Тайм-аут сохраняет ожидание и время следующей проверки. Повторный одинаковый ответ не создаёт новую попытку и не дублирует конечное событие. Неопознаваемый ответ направляется ИТ-поддержке.','Статус соответствует подтверждённому результату; история проверки доступна.'),
('UC-09','Получить управленческий отчёт','Директор или менеджер','F-11','Пользователь имеет доступ к соответствующей области данных; события процесса зарегистрированы.','Пользователь задаёт период и фильтры. Система рассчитывает число операций, время подготовки, долю успешных первых отправок и актуальность источников. Отображает итог и детализацию до карточек.','При отсутствии наблюдений выводится «нет данных», а не нулевое качество. Операции без завершения показываются отдельно от завершённых.','Сформирован воспроизводимый отчёт с периодом, фильтрами и правилами расчёта.'),
('UC-10','Управлять доступом','Администратор','F-12, F-10','Администратор вошёл под индивидуальной учётной записью; есть основание изменения прав.','Администратор создаёт или блокирует пользователя, назначает роль и подтверждает изменение. Система проверяет полномочия, сохраняет права и событие аудита; новые ограничения применяются к последующим запросам.','Попытка обычного пользователя изменить роли отклоняется. Блокировка не удаляет связанные записи автора из истории.','Матрица доступа обновлена; изменения прослеживаются по автору и времени.'),
]

def practice8(r,f):
    r.start(8,'исследовать требования через классы и объекты предметной области, построить UML-диаграмму вариантов использования и специфицировать каждый прецедент.')
    r.h('Этапы выполнения работы');r.p('Выделены устойчивые понятия и их связи, внешние роли и цели взаимодействия с системой. Из реестра требований сформированы десять прецедентов. Диаграмма разделена на два согласованных представления одной системы: подготовка данных и управление публикацией. Используется нотация UML [13].')
    r.table('Словарь предметной области',['Термин / класс','Определение и основные свойства'],[
    ['Компонент','Комплектующая: внутренний код, тип, технические характеристики, масса.'],['Предложение поставщика','Цена и доступность компонента в определённом источнике на указанную дату.'],['BOM и версия BOM','Спецификация компьютера и её конкретный состав; номер, состояние, автор, согласующий.'],['Строка BOM','Ссылка на компонент и его количество в одной версии спецификации.'],['Правило совместимости','Условие допустимого сочетания характеристик с уровнем критичности и версией.'],['Протокол проверки','Результаты применения правил к одной версии BOM.'],['Расчётная ведомость','Снимок цен, затрат на сборку, наценки и массы; рассчитанные показатели.'],['Карточка товара','Описание компьютерной системы для заданной категории и канала; внутренний и внешний идентификаторы.'],['Изображение','Файл и сведения о его соответствии конкретной конфигурации.'],['Попытка публикации','Неизменяемый отправленный пакет, время, автор, результат и идентификатор обработки.'],['Событие аудита','Кто, когда, над каким объектом и какое значимое действие выполнил.'],['Пользователь и роль','Индивидуальная учётная запись и разрешённый набор операций.'],
    ],[4.5,11])
    r.h('Классы и отношения')
    r.p('Одна BOM имеет одну или несколько версий; каждая версия содержит одну или несколько строк, а строка ссылается на один компонент. Компонент может входить во множество версий. Карточка в выбранном состоянии связана с одной версией BOM, но её история хранит прежние связи. У карточки может быть много попыток публикации; каждая попытка относится ровно к одному зафиксированному пакету. Изображение может использоваться в нескольких карточках при подтверждённом соответствии конфигурации.')
    r.p('Контроллеры импорта, BOM, расчёта, карточки и публикации координируют сценарии; сущности хранят предметное состояние. Экран карточки является граничным объектом. Например, объект bomVersion:ВерсияBOM содержит состав конкретной конфигурации, а publication:ПопыткаПубликации связывает её с одной отправкой. Эта граница помогает отделить правила предметной области от внешнего интерфейса Ozon.')
    r.table('Участники и варианты использования',['Актор','Связь','Прецеденты'],[
    ['Менеджер','Ассоциация','UC-01, UC-04, UC-06, UC-07, UC-08, UC-09'],['Производственный специалист','Ассоциация','UC-02, UC-03'],['Дизайнер','Ассоциация','UC-05'],['Директор','Ассоциация','UC-09'],['Администратор','Ассоциация','UC-10'],['Ozon','Ассоциация внешней системы','UC-07, UC-08'],['UC-02 → UC-03','«include»','Согласование всегда включает проверку совместимости.'],['UC-06 → UC-04','«include»','Формирование утверждаемого пакета включает актуальный расчёт.'],
    ],[4,3.5,8])
    r.orient(True);r.h('Диаграмма вариантов использования');r.fig(f['uc_data'],'Прецеденты подготовки данных и карточки');r.fig(f['uc_pub'],'Прецеденты публикации, контроля и доступа')
    r.orient(False);r.h('Спецификации прецедентов')
    for code,name,actor,req,pre,main,alt,post in CASES:
        r.h(code+' — '+name)
        r.p('Участники: '+actor+'. Требования: '+req+'. Общие требования F-10 и F-12 применяются ко всем изменяющим операциям.')
        r.p('Предусловия: '+pre)
        r.p('Основной поток: '+main)
        r.p('Альтернативы и ошибки: '+alt)
        r.p('Постусловия: '+post)
    r.h('Выводы');r.p('Построена модель из шести акторов и десяти прецедентов. Для каждого определены предусловия, обязанности участника и системы, альтернативные ветви и результат. Связи «include» применены только к обязательным подоперациям. Сценарии уточняют требования практики 6 и служат основой динамических UML-моделей и тестов.')
